def _append_only() -> None:
    """Triggers that refuse every UPDATE, DELETE and TRUNCATE."""
    op.execute("CREATE OR REPLACE FUNCTION erpclaw_refuse_change() RETURNS trigger LANGUAGE plpgsql AS $$ "
               "BEGIN RAISE EXCEPTION 'append-only table %: % refused', TG_TABLE_NAME, TG_OP; END $$")
    for table in APPEND_ONLY:
        op.execute(f"CREATE TRIGGER {table}_append_only BEFORE UPDATE OR DELETE ON {table} "
                   "FOR EACH ROW EXECUTE FUNCTION erpclaw_refuse_change()")
        # TRUNCATE fires no row triggers, so it needs its own statement trigger.
        op.execute(f"CREATE TRIGGER {table}_no_truncate BEFORE TRUNCATE ON {table} "
                   "FOR EACH STATEMENT EXECUTE FUNCTION erpclaw_refuse_change()")


